import { FC } from 'react';

type LoadingType = 'spinner' | 'dots' | 'circular';
type LoadingSize = 'sm' | 'md' | 'lg';
interface LoadingProps {
    /** 加载类型 */
    type?: LoadingType;
    /** 尺寸 */
    size?: LoadingSize;
    /** 颜色 */
    color?: string;
    /** 加载文字 */
    text?: string;
    /** 文字与图标的间距方向 */
    direction?: 'horizontal' | 'vertical';
    /** 自定义类名 */
    className?: string;
}

declare const Loading: FC<LoadingProps>;

export { Loading, Loading as default };
export type { LoadingProps, LoadingSize, LoadingType };
